function exerciseSetsForUnit(unit){
 const groups=new Map();
 for(const item of unit.analysis?.exercises||[]){if(!Number.isInteger(Number(item.setIndex)))continue;const key=Number(item.setIndex),items=groups.get(key)||[];items.push(item);groups.set(key,items)}
 return [...groups.entries()].sort(([a],[b])=>a-b).map(([setIndex,items])=>{items.sort((a,b)=>Number(a.no)-Number(b.no));return {setIndex,title:items[0].setTitle||`Bộ ${setIndex}`,instruction:items[0].instruction||'',kind:items[0].kind||'other',rawText:items.map(x=>x.prompt||'').join('\n'),items}});
}
function hasExerciseAnswer(item){const value=item?.answer;return Array.isArray(value)?value.some(x=>String(x||'').trim()):value&&typeof value==='object'?Object.keys(value).length>0:!!String(value||'').trim()}
function answerProgress(message,current,total){if(win&&!win.isDestroyed())win.webContents.send('progress',{exerciseAnswers:true,message,current,total})}
function quotaFailure(error){return /429|RESOURCE_EXHAUSTED|quota|rate.?limit|hạn mức/i.test(safeErr(error))}
async function generateExerciseAnswers(book,units){
 requireAdmin();if(answerGenerationRunning)throw Error('Đang có lượt tạo đáp án khác chạy.');
 answerGenerationRunning=true;answerGenerationStopRequested=false;
 const allSets=[];
 for(const unit of units)for(const set of exerciseSetsForUnit(unit))allSets.push({unit,set});
 const supported=new Set(['multiple_choice','true_false','fill_blank','verb_form','matching','definition_to_word','short_answer']);
 const tasks=allSets.filter(({set})=>(set.kind==='ipa_to_word'||supported.has(set.kind))&&!set.items.some(hasExerciseAnswer));
 const skippedAnswered=allSets.filter(({set})=>set.items.some(hasExerciseAnswer)).length;
 let completed=0,success=0,failed=0,stopped=false,quotaStopped=false;const errors=[];
 try{
  if(tasks.some(({set})=>set.kind!=='ipa_to_word'&&supported.has(set.kind))&&!readProviderKeys('gemini').length)throw Error('Chưa cấu hình Gemini API key để tạo đáp án.');
  for(const task of tasks){
   if(answerGenerationStopRequested){stopped=true;break}
   const {unit,set}=task;completed++;
   answerProgress(`Đang tạo đáp án ${completed}/${tasks.length}: ${unit.title} · ${set.title}`,completed,tasks.length);
   const items=set.items,kind=set.kind;
   try{
    if(kind==='ipa_to_word'){
     const bookGlossary=book.units.flatMap(x=>x.analysis?.vocabulary||[]),unitGlossary=unit.analysis?.vocabulary||[];
     for(const item of items){if(hasExerciseAnswer(item))continue;const ipa=String(item.prompt||'').match(/(?:\/[^/\r\n]+\/|\[[^\]\r\n]+\])/u)?.[0]||item.ipa||'';const match=findIpaGlossaryMatch(ipa,[...unitGlossary,...bookGlossary]);if(match){item.answer=match.term;item.evidence=match.evidence||'';item.answerStatus='verified_ai';item.answerConfidence=1}else item.answerStatus='needs_review';item.answerCheck=null}
    }else if(supported.has(kind)){
     const unresolved=items.filter(item=>!hasExerciseAnswer(item));
     const readings=(unit.analysis?.readings||[]).map(x=>x.content||'').join('\n\n'),readingText=readings.slice(0,30000);
     const solved=await ai.solveExerciseSet({bookTitle:book.title,unitTitle:unit.title,reading:readingText,glossary:unit.analysis?.vocabulary||[],grammar:unit.analysis?.grammar||[],set:{...set,items:unresolved}});
     for(const item of unresolved){const candidate=(solved.items||[]).find(x=>Number(x.no)===Number(item.no));if(candidate)Object.assign(item,verifyExerciseAnswer(item,candidate,readingText,unit.source||''));else item.answerStatus='needs_review';item.answerCheck=null}
    }else continue;
    const setSuccess=items.filter(item=>item.answerStatus==='verified_ai'||item.answerStatus==='confirmed').length;
    const setFailed=items.filter(item=>item.answerStatus==='needs_review').length;
    success+=setSuccess;failed+=setFailed;
    await persistExerciseItems(unit);save();
   }catch(error){
     for(const item of items)if(!hasExerciseAnswer(item)&&supported.has(kind))item.answerStatus='needs_review';
    failed+=items.filter(item=>item.answerStatus==='needs_review').length;errors.push(`${unit.title} · ${set.title}: ${safeErr(error)}`);await persistExerciseItems(unit).catch(()=>{});save();
    if(quotaFailure(error)){quotaStopped=true;answerProgress(`Đã dừng do hạn mức AI: ${completed}/${tasks.length} bộ.`,completed,tasks.length);break}
   }
   win?.webContents?.send('unit-updated',{bookId:book.id,unitId:unit.id});
  }
  const message=stopped?`Đã dừng. Đã xử lý ${completed}/${tasks.length} bộ bài.`:quotaStopped?`Đã dừng do hạn mức AI sau ${completed}/${tasks.length} bộ.`:tasks.length?`Hoàn tất: ${success} câu có đáp án, ${failed} câu cần duyệt; bỏ qua ${skippedAnswered} bộ đã có đáp án.`:'Không có bộ bài thuộc phạm vi tạo đáp án tự động cần xử lý.';
  answerProgress(message,completed,tasks.length);
  return {success,failed,completed,total:tasks.length,skippedAnswered,stopped,quotaStopped,errors};
 }finally{answerGenerationRunning=false;answerGenerationStopRequested=false}
}

