handle('ask',async({bookId,unitId,question,term})=>{requireLogin();const b=db.books.find(x=>x.id===bookId),u=b?.units.find(x=>x.id===unitId);if(!u)throw Error('Hãy chọn Unit cần hỏi.');if(!readKey())throw Error('Hãy nhập Gemini API key trong Cài đặt.');return ai.ask({bookTitle:b.title,branch:b.branch,unitTitle:u.title,source:u.source,analysis:u.analysis,question:String(question||''),term:String(term||'')})});
handle('delete-book',async(id)=>{requireAdmin();const i=db.books.findIndex(b=>b.id===id);if(i<0)throw Error('Không tìm thấy giáo trình.');const removed=db.books[i];if(removed.id)await supabaseRest(`books?id=eq.${removed.id}`,{method:'DELETE',prefer:'return=minimal'});db.books.splice(i,1);db.sessions=db.sessions.filter(s=>s.bookId!==id);for(const k of Object.keys(db.reviewStatus||{}))if(k.startsWith(id+':'))delete db.reviewStatus[k];save();return true});
handle('review-mark',async({key,known})=>{requireLogin();const reviewKey=String(key),ownKey=`${currentUser.id}:${reviewKey}`,previous=db.reviewStatus[ownKey],now=Date.now(),wasKnown=previous&&typeof previous==='object'?!!previous.known:previous===true;let repetitions=known?(wasKnown?(previous.repetitions||0)+1:1):0,ease=typeof previous==='object'&&Number(previous.ease)>1.3?Number(previous.ease):2.5,intervalDays;if(!known){ease=Math.max(1.3,ease-.2);intervalDays=1/24}else{intervalDays=repetitions===1?1:repetitions===2?6:Math.max(1,Math.round((Number(previous.intervalDays)||6)*ease))}const status={known:!!known,repetitions,ease,intervalDays,lastReviewed:new Date(now).toISOString(),dueAt:new Date(now+intervalDays*86400000).toISOString()},unitId=reviewKey.split(':')[1],term=reviewKey.split(':').slice(2).join(':');await supabaseRest('vocabulary_reviews?on_conflict=user_id,review_key',{method:'POST',prefer:'resolution=merge-duplicates,return=minimal',body:{user_id:currentUser.id,review_key:reviewKey,unit_id:unitId,term,repetitions,ease_factor:ease,interval_days:intervalDays,due_at:status.dueAt,last_reviewed:status.lastReviewed}});db.reviewStatus[ownKey]=status;save();return status});
handle('backup',async()=>{requireLogin();const r=await dialog.showSaveDialog(win,{defaultPath:'MEAI-Next-backup.json',filters:[{name:'MEAI backup',extensions:['json']}]});if(r.canceled)return false;fs.writeFileSync(r.filePath,JSON.stringify({version:3,books:db.books,settings:{model:db.settings.model}},null,2),'utf8');return true});
handle('export-book',async(id)=>{requireLogin();const b=db.books.find(x=>x.id===id);if(!b)throw Error('Không tìm thấy giáo trình.');const r=await dialog.showSaveDialog(win,{defaultPath:`${b.title.replace(/[\\/:*?"<>|]/g,'_')}-MEAI.json`,filters:[{name:'MEAI unit data',extensions:['json']}]});if(r.canceled)return false;fs.writeFileSync(r.filePath,JSON.stringify(b,null,2),'utf8');return true});
app.whenReady().then(()=>{load();ai=new AI(readProviderKeys,()=>db.settings.model,assertAIQuota,recordAIUsage,notifyAIWait);createWindow();app.on('activate',()=>{if(BrowserWindow.getAllWindows().length===0)createWindow()})});
app.on('window-all-closed',()=>{if(process.platform!=='darwin')app.quit()});
